import{_ as s,o as e,c as n,ag as t}from"./chunks/framework.BJFNwp4n.js";const u=JSON.parse('{"title":"NFS Client","description":"","frontmatter":{"date":"2022-11-23T00:00:00.000Z"},"headers":[],"relativePath":"zh/tools/nfs-client.md","filePath":"zh/tools/nfs-client.md"}'),i={name:"zh/tools/nfs-client.md"};function l(p,a,o,d,c,r){return e(),n("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1669161600000"},[...a[0]||(a[0]=[t(`<h1 id="nfs-client" tabindex="-1">NFS Client <a class="header-anchor" href="#nfs-client" aria-label="Permalink to &quot;NFS Client&quot;">​</a></h1><h2 id="概览" tabindex="-1">概览 <a class="header-anchor" href="#概览" aria-label="Permalink to &quot;概览&quot;">​</a></h2><p>NFS Client可以挂载NFS Server管理的共享目录，使得多台服务器可以风筒管理共享目录，NFS支持多点挂载，即在多个服务器上同时挂载同一个共享目录。</p><h2 id="环境说明" tabindex="-1">环境说明 <a class="header-anchor" href="#环境说明" aria-label="Permalink to &quot;环境说明&quot;">​</a></h2><ul><li>NFS Server所在服务器IP：192.168.1.240</li><li>NFS Client安装服务器IP：192.168.1.241</li></ul><h2 id="安装nfs-client" tabindex="-1">安装NFS Client <a class="header-anchor" href="#安装nfs-client" aria-label="Permalink to &quot;安装NFS Client&quot;">​</a></h2><h3 id="安装-nfs-工具及其依赖" tabindex="-1">安装 NFS 工具及其依赖 <a class="header-anchor" href="#安装-nfs-工具及其依赖" aria-label="Permalink to &quot;安装 NFS 工具及其依赖&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sudo yum install nfs-utils</span></span></code></pre></div><h3 id="客户端配置" tabindex="-1">客户端配置 <a class="header-anchor" href="#客户端配置" aria-label="Permalink to &quot;客户端配置&quot;">​</a></h3><ol><li><p>设置 rpcbind 服务的开机启动</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sudo systemctl enable rpcbind</span></span></code></pre></div></li><li><p>启动 rpcbind 服务</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sudo systemctl start rpcbind</span></span></code></pre></div></li></ol><p>客户端不需要打开防火墙，因为客户端时发出请求方，网络能连接到服务端即可。<br> 客户端也不需要开启 NFS 服务，因为不共享目录。</p><h2 id="客户端连接-nfs-server" tabindex="-1">客户端连接 NFS Server <a class="header-anchor" href="#客户端连接-nfs-server" aria-label="Permalink to &quot;客户端连接 NFS Server&quot;">​</a></h2><ol><li><p>查询NFS Server的共享目录</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ showmount -e 192.168.1.240</span></span>
<span class="line"><span>Export list for 192.168.1.240:</span></span>
<span class="line"><span>/home/nfs/data *</span></span></code></pre></div></li><li><p>在客户端创建目录</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sudo mkdir /home/nfs/mount-data</span></span></code></pre></div></li><li><p>挂载共享目录</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sudo mount -t nfs 192.168.1.240:/home/nfs/data /home/nfs/mount-data</span></span></code></pre></div></li><li><p>查看挂载</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ mount</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>192.168.1.240:/home/nfs/data on /home/nfs/mount-data type nfs4 (rw,relatime,vers=4.1,rsize=1048576,wsize=1048576,namlen=255,hard,proto=tcp,timeo=600,retrans=2,sec=sys,clientaddr=192.168.1.241,local_lock=none,addr=192.168.1.240)</span></span></code></pre></div></li></ol><p>这说明已经挂载成功了。</p><h2 id="测试-nfs" tabindex="-1">测试 NFS <a class="header-anchor" href="#测试-nfs" aria-label="Permalink to &quot;测试 NFS&quot;">​</a></h2><ol><li><p>在客户端向共享目录创建一个文件</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ cd /home/nfs/mount-data</span></span>
<span class="line"><span>$ sudo touch abc</span></span></code></pre></div></li><li><p>在NFS 服务端 <code>192.168.1.240</code> 查看一下</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ cd /home/nfs/data</span></span>
<span class="line"><span>$ ll</span></span>
<span class="line"><span>total 0</span></span>
<span class="line"><span>-rw-r--r--. 1 root  7 Mar 10 03:54 abc</span></span></code></pre></div></li></ol><p>可以看到，共享目录已经写入了。</p>`,17)])])}const b=s(i,[["render",l]]);export{u as __pageData,b as default};
